  data = $isp2json${"slug": "intermediate-spanish-ii", "title": "Intermediate Spanish II", "description": "Move students from intermediate grammar control into upper-intermediate communication, interpretation, argument, cultural analysis, and revised academic writing.", "topics": [{"id": "aa4aa535-f4fc-4635-b880-6d7167d43a88", "type": "topic", "title": "Past Subjunctive", "description": "This unit extends subjunctive control into past, hypothetical, polite, and counterfactual contexts. Students learn to discuss what people wanted, doubted, recommended, feared, or imagined in relation to past and unreal situations.", "children": [{"id": "5df0da24-dce5-4bcb-8bb3-1838ab33551b", "type": "subtopic", "title": "Formation and core patterns", "children": [{"id": "14e906ca-c99f-426b-97fc-29c74b620992", "type": "concept", "title": "third-person preterite base"}, {"id": "2782cdb5-d0bc-4950-ba6b-a6c540ffbeb6", "type": "concept", "title": "-ra endings"}, {"id": "1294066d-4032-4446-8731-580d89b4d223", "type": "concept", "title": "-se recognition"}, {"id": "0e60a5fc-b94a-411f-822b-8686f88e9871", "type": "concept", "title": "irregular stems"}], "description": "Build accurate imperfect subjunctive forms and recognize both -ra and -se variants."}, {"id": "d0cf57ab-15f6-49c9-8f9a-4298e8489873", "type": "subtopic", "title": "Past influence, emotion, and doubt", "children": [{"id": "d46f7fe3-8e38-4693-8baf-7e8ab1520905", "type": "concept", "title": "queria que"}, {"id": "ee4c74ac-f9a4-4b2d-959b-f2752daa5ce1", "type": "concept", "title": "me sorprendio que"}, {"id": "646e81f0-ec10-4378-9502-7adb88d9a5f4", "type": "concept", "title": "dudaba que"}, {"id": "b0a2a60c-97df-4bed-ad38-aa41aa73fd61", "type": "concept", "title": "era importante que"}], "description": "Use past-tense main clauses to report wishes, reactions, recommendations, and uncertainty."}, {"id": "5e43259d-f66a-4f38-88ef-a2bda1c72f5b", "type": "subtopic", "title": "Unreal and hypothetical meaning", "children": [{"id": "833f41