1ab-adb4-50c43ad16efa", "type": "subtopic", "title": "Past perfect", "children": [{"id": "9b5f7601-39aa-4532-a273-02fa126a2a89", "type": "concept", "title": "habia + participle"}, {"id": "bd0beb00-dae7-48f7-94a5-f3651a865186", "type": "concept", "title": "narrative backstory"}, {"id": "d4de6ed1-645d-427a-b2c3-9fab64b9b01b", "type": "concept", "title": "cause and consequence"}, {"id": "880923ba-f38d-4403-b169-9ccdead09339", "type": "concept", "title": "time markers"}], "description": "Show what had happened before another past event."}, {"id": "fbdac816-48bd-461b-8e8d-2262ee5be46f", "type": "subtopic", "title": "Future and conditional perfect", "children": [{"id": "5ed43e9d-f52d-40c4-b940-8a7c904b0ea8", "type": "concept", "title": "habre"}, {"id": "cde2ff41-ae4c-4cef-a0f0-ce5162badfe8", "type": "concept", "title": "habria"}, {"id": "6bd0901f-fbb1-4fd7-9c8f-4933687c5970", "type": "concept", "title": "probability"}, {"id": "3bce7fdb-5b11-4e63-8ff4-fdc78be6e683", "type": "concept", "title": "speculation"}], "description": "Express what will have happened or what would have happened under certain conditions."}, {"id": "2b0f66be-f03c-4bce-bd3a-2c0971b11203", "type": "subtopic", "title": "Perfect subjunctive recognition", "children": [{"id": "4f181148-b082-437f-b123-70836a90dc84", "type": "concept", "title": "haya"}, {"id": "e9956932-aadb-464a-a464-1bf79c35eb4d", "type": "concept", "title": "hubiera"}, {"id": "6bf24485-9872-4665-b344-dc6f49005216", "type": "concept", "title": "doubt and evaluation"}, {"id": "e0f426bb-14d2-45ad-8f44-db8176e7b20c", "type": "concept", "title": "editing for sequence"}], "description": "Recognize and produce high-frequency perfect subjunctive structures in advanced contexts."}]}, {"id": "2e8cdb21-1898-4030-af2b-384b0d7260b1", "type": "topic", "title": "Si Clauses", "description": "This unit helps students reason in Spanish. They learn to build conditional sentences for real possibilities, unlikely scenarios, advice, regret, and counterfactual reflection.", "children": [{"id": "7ede27a3-7cef-480e-b0ce-62ead4937625", "type": "subtopic", "title": "Real conditions", "children": [{"id": "a68c07c1-dc55-4d5d-9e92-9825a6cba3a6", "type": "concept", "title": "si + present"}, {"id": "b118c5c7-6249-4366-b530-f7f5687c49e0", "type": "concept", "title": "future result"}, {"id": "e7d45d32-2b70-40b9-b636-e35b4374ac99", "type": "concept", "title": "imperative result"}, {"id": "8d51c650-1f72-40d7-8bf9-3be6f6b300b9", "type": "concept", "title": "habitual conditions"}], "description": "Use present and future patterns to discuss likely outcomes and practical plans."}, {"id": "b952b17a-ebae-4d7e-94af-677691f43b36", "type": "subtopic", "title": "Hypothetical conditions", "children": [{"id": "6ae11d0d-9cea-4380-944f-64f5a59482c8", "type": "concept", "title": "si tuviera"}, {"id": "fa6890aa-8086-4494-861f-23839fe65ed5", "type": "concept", "title": "seria"}, {"id": "539d620b-538a-429f-9458-d5480ff24efe", "type": "concept", "title": "podria"}, {"id": "c5dcbb4e-685d-48ff-a6e7-5df7d14093af", "type": "concept", "title": "recommendation tasks"}], "description": "Use imperfect subjunctive with conditional to discuss unlikely or imagined situations."}, {"id": "4dbc520e-1a4e-47de-9cba-23995c0c26a9", "type": "subtopic", "title": "Past counterfactuals", "children": [{"id": "df2c8b4b-07f2-40ad-ae73-b97c0277eaf3", "type": "concept", "title": "si hubiera"}, {"id": "1862766c-98c0-48f0-8ccf-852c246744fc", "type": "concept", "title": "habria"}, {"id": "ad9b6a35-2841-435d-b668-f0523db06b49", "type": "concept", "title": "reflection"}, {"id": "af8fec06-5afd-46c8-a38a-7085c3d943af", "type": "concept", "title": "historical scenarios"}], "description": "Use pluperfect subjunctive and conditional perfect to discuss regret or alternate outcomes."}, {"id": "494a03ff-c5e3-48cd-bf13-5a0482ff4f73", "type": "subtopic", "title": "Conditional argumentation", "children": [{"id": "a48296bf-2ea9-4c3e-95a7-d22d7268746e", "type": "concept", "title": "problem solving"}, {"id": "642837fb-14c2-44ab-8ade-a408bc531f05", "type": "concept", "title": "policy scenarios"}, {"id": "60659938-8466-42ef-acd4-d078d11364d3", "type": "concept", "title": "debate language"}, {"id": "8afabf09-dcb8-4d0c-826c-d0bfbd375712", "type": "concept", "title": "cause-effect logic"}], "description": "Use si clauses to support claims, recommendations, and ethical reasoning."}]}, {"id": "a6e3e4dd-f7fa-4d1f-ae9b-9696366c6ce8", "type": "topic", "title": "Passive and Impersonal Constructions", "description": "Students learn to describe processes, report information, and discuss general practices without overusing personal subjects. These constructions are essential for academic, journalistic, and formal Spanish.", "children": [{"id": "bf1e2134-196b-49cb-8553-6b20e366b5a0", "type": "subtopic", "title": "Se impersonal", "children": [{"id": "ca408615-4f26-4cbc-8120-3fe5a4cf1331", "type": "concept", "title": "se dice"}, {"id": "4d28bcda-6385-4acc-8721-35e50ca91126", "type": "concept", "title": "se necesita"}, {"id": "eb5244c2-8443-4152-a6a5-8c2744aa3ebe", "type": "concept", "title": "se puede"}, {"id": "44438ac7-c067-42b6-8cfb-e51c71e828c1", "type": "concept", "title": "public norms"}], "description": "Make general statements about what people do, say, believe, or need."}, {"id": "b07a397a-334e-4a6d-bab5-6e323484a005", "type": "subtopic", "title": "Passive se", "children": [{"id": "4733d8c0-9c9a-45da-9762-d71e816a207f", "type": "concept", "title": "se venden"}, {"id": "9cfb9013-23bb-436e-a01a-2e8eb94063b1", "type": "concept", "title": "se construyo"}, {"id": "db388511-43c0-4a36-ac8f-67fcab27ff2a", "type": "concept", "title": "agreement"}, {"id": "d4cf82d6-da9c-4b96-b9c2-4dbda38fc6c5", "type": "concept", "title": "process description"}], "description": "Describe actions done to things or groups while keeping the actor unstated."}, {"id": "a8e317ec-61ec-4745-85e4-f3fcdfc68ae8", "type": "subtopic", "title": "Ser + past participle", "children": [{"id": "cc9c4e30-8e0f-40b2-9537-529b5685a8d6", "type": "concept", "title": "agent with por"}, {"id": "20d6d26e-3b31-4082-88b8-7d79dd7ece71", "type": "concept", "title": "agreement"}, {"id": "f76bb442-2b11-4ec0-b8f5-dbea4478845c", "type": "concept", "title": "formal register"}, {"id": "ca67b63e-9e95-4532-93f9-b2e401cbe6c7", "type": "concept", "title": "event reporting"}], "description": "Recognize and use formal passive structures in news, history, and academic prose."}, {"id": "1aaa3f8f-d05e-4aae-8811-ccccca2fa457", "type": "subtopic", "title": "Impersonal expressions with infinitives", "children": [{"id": "752c244d-79c3-47bc-8066-bba92f19fba3", "type": "concept", "title": "hay que"}, {"id": "d089adae-3f90-4b49-ae63-2293da018fdb", "type": "concept", "title": "es necesario"}, {"id": "16a03d63-f451-4cf3-a56d-098b0298d9f3", "type": "concept", "title": "conviene"}, {"id": "f8ffe2da-d874-411b-a739-b4af0080b6fc", "type": "concept", "title": "vale la pena"}], "description": "Build concise academic and practical statements."}]}, {"id": "e25ae325-7859-4743-8a2f-765093115f51", "type": "topic", "title": "Advanced Pronoun Review", "description": "This unit consolidates pronoun systems that often remain fragile after first-year study. Students refine object pronouns, reflexives, reciprocal meaning, se constructions, and pronoun placement in complex sentences.", "children": [{"id": "01bac2b9-a4b1-44f0-9348-379758a764f4", "type": "subtopic", "title": "Direct and indirect object pronouns", "children": [{"id": "f9bef91c-88c6-4862-a523-3379c230a3da", "type": "concept", "title": "lo/la/los/las"}, {"id": "b549bfa7-3574-42ba-9bd1-b567dc344831", "type": "concept", "title": "le/les"}, {"id": "5eb10e7e-153b-40fe-ad7c-b6165dd6d3ec", "type": "concept", "title": "personal a"}, {"id": "0f9f0205-e7e2-4d16-a9d1-1c2c54a2666d", "type": "concept", "title": "clarifying phrases"}], "description": "Strengthen accuracy when replacing people, things, and recipients."}, {"id": "97b72620-df07-47c9-9b70-2962020fc173", "type": "subtopic", "title": "Double object pronouns", "children": [{"id": "437de0eb-f9ec-4e92-9c32-6269ac908a66", "type": "concept", "title": "se lo"}, {"id": "19dc776c-d47f-4cb7-8690-ba708b63020b", "type": "concept", "title": "se la"}, {"id": "0c7690a0-fa1c-4d9e-baef-56690e9a700d", "type": "concept", "title": "placement"}, {"id": "45dd7aef-9db7-4c61-93eb-9345903abef3", "type": "concept", "title": "written accent rules"}], "description": "Use two pronouns together with correct order and se substitution."}, {"id": "75a63d34-c7fe-4485-a0ab-fef09c3431f5", "type": "subtopic", "title": "Reflexive, reciprocal, and pronominal verbs", "children": [{"id": "93468cee-2f42-4fd5-b6e4-6d913a6a0935", "type": "concept", "title": "acordarse"}, {"id": "be8df535-8b0d-4380-b52c-790b58c7eaa0", "type": "concept", "title": "darse cuenta"}, {"id": "0d3533fb-a0c3-467a-bc9b-88a0c943652c", "type": "concept", "title": "quejarse"}, {"id": "31d38706-8cef-4c25-95dd-34d92214c497", "type": "concept", "title": "reciprocal actions"}], "description": "Understand how pronouns can change meaning, perspective, or verb behavior."}, {"id": "3d9096fb-12bc-41f6-926c-0f5dedf38993", "type": "subtopic", "title": "Pronoun placement in complex forms", "children": [{"id": "e94ca3f8-ee31-4349-af43-49a9fc2c472d", "type": "concept", "title": "attached pronouns"}, {"id": "1af3c45f-8234-4bb1-a153-5a778461e7da", "type": "concept", "title": "before conjugated verbs"}, {"id": "489b3370-4824-439c-b189-c7a0a0fbbdf3", "type": "concept", "title": "accent marks"}, {"id": "0177a533-eff8-4856-9aca-c0301dbddc97", "type": "concept", "title": "editing routines"}], "description": "Place pronouns with infinitives, gerunds, commands, and perfect tenses."}]}, {"id": "2254ccb5-f79e-4845-b535-8b397e1eac6d", "type": "topic", "title": "Register and Formality", "description": "Students learn that strong Spanish is socially appropriate Spanish. This unit focuses on audience, context, politeness, regional variation, and choices that distinguish casual conversation from academic or professional communication.", "children": [{"id": "37eef11f-aa98-44d7-91be-99397ca924d5", "type": "subtopic", "title": "Tu, usted, and ustedes", "children": [{"id": "e229fc8f-d4ae-46a8-9807-e0856a5cf7b7", "type": "concept", "title": "formal requests"}, {"id": "d6110003-f024-4445-842c-b04c273a5936", "type": "concept", "title": "peer conversation"}, {"id": "87aa9827-618f-4069-bebe-43d54f3f0431", "type": "concept", "title": "regional norms"}, {"id": "262ea1ea-e6a4-4b78-97eb-7cad55e8392e", "type": "concept", "title": "email openings"}], "description": "Choose forms of address according to relationship, region, and communicative purpose."}, {"id": "bf90c750-0a1d-4120-b5ce-2bee236d9ab7", "type": "subtopic", "title": "Politeness and softening strategies", "children": [{"id": "4d5df728-26ee-452b-a685-919600303c63", "type": "concept", "title": "conditional politeness"}, {"id": "e3b55d75-ce23-442b-8c96-0944cf4ea242", "type": "concept", "title": "quisiera"}, {"id": "3dd16712-7364-4100-9152-04418934e6c6", "type": "concept", "title": "me parece que"}, {"id": "c479e97f-fa06-423b-9c97-c19c7fd4d753", "type": "concept", "title": "mitigating phrases"}], "description": "Make requests, disagreement, and advice sound appropriate rather than abrupt."}, {"id": "21f43486-a982-4188-b03f-d5c8d5f52e90", "type": "subtopic", "title": "Academic and professional register", "children": [{"id": "05e78ed0-88f4-4fd6-98ba-763f56db8be6", "type": "concept", "title": "por consiguiente"}, {"id": "010e71de-a9b3-4c5e-bda8-26098331cba8", "type": "concept", "title": "sin embargo"}, {"id": "33aadc5b-dfb9-4980-a684-7fdbd8a0005c", "type": "concept", "title": "segun"}, {"id": "1ab9c3a4-c049-4f17-8248-c249b765da2a", "type": "concept", "title": "formal verbs"}], "description": "Use vocabulary, connectors, and tone suitable for presentations and formal writing."}, {"id": "b14240a8-9ffc-4887-a4c8-8ee06886644a", "type": "subtopic", "title": "Regional and cultural variation", "children": [{"id": "17e70398-ce1a-4b7a-844b-ca31cfba7223", "type": "concept", "title": "vos recognition"}, {"id": "cd46399d-4190-4b48-887c-39fe583f9c78", "type": "concept", "title": "ustedes/vosotros"}, {"id": "96255d8c-557e-4607-9483-338223719c7b", "type": "concept", "title": "loanwords"}, {"id": "adc76add-2f45-4ddb-b44e-37f5d6121723", "type": "concept", "title": "dialect awareness"}], "description": "Recognize that Spanish norms vary across communities and media contexts."}]}, {"id": "1d9346d2-2512-4973-8553-745b0abd3b3e", "type": "topic", "title": "Argument and Opinion", "description": "This unit helps students move from preference statements to reasoned claims. Students learn to state a position, support it with evidence, respond to alternatives, and use persuasive language in speech and writing.", "children": [{"id": "5e06cd14-9305-4df9-b51b-e3764854d862", "type": "subtopic", "title": "Claims and reasons", "children": [{"id": "8db7e1fb-440a-499b-822b-e51694d09f5e", "type": "concept", "title": "tesis"}, {"id": "1f12e803-23f1-49d3-8c46-064744de999c", "type": "concept", "title": "porque"}, {"id": "4e8f30a1-d587-48eb-ab9f-205a220fd185", "type": "concept", "title": "evidence"}, {"id": "018899af-bf47-40e8-b64f-db7db917c8cd", "type": "concept", "title": "examples"}], "description": "Build clear argumentative statements that go beyond simple likes and dislikes."}, {"id": "5b44c70e-5d94-429a-9c0d-fbe1ad38324a", "type": "subtopic", "title": "Agreement and disagreement", "children": [{"id": "e2b5440f-985a-43a2-ad3b-6fd3447c4af8", "type": "concept", "title": "estoy de acuerdo"}, {"id": "d8e74c12-66c2-401d-92c0-3f5766909169", "type": "concept", "title": "no estoy convencido"}, {"id": "ca8a7b84-b331-49f4-830d-a3db98307b36", "type": "concept", "title": "por otra parte"}, {"id": "4b83df14-246a-4b3e-9bbf-d7bc6b0d2f38", "type": "concept", "title": "matizar"}], "description": "Participate in respectful discussion using precise conversational moves."}, {"id": "1ad77dc4-5c9b-4b42-bbc2-98a4b38a13ba", "type": "subtopic", "title": "Evidence from texts and media", "children": [{"id": "b4b72016-4cab-42ae-9eaa-7c514a68f8f6", "type": "concept", "title": "citation phrases"}, {"id": "3fd66344-eeae-4ecd-8387-dfe5dfea0e77", "type": "concept", "title": "paraphrase"}, {"id": "154cdb7b-715a-402a-ab92-77880fd6a052", "type": "concept", "title": "summary"}, {"id": "bf1419fc-dd50-4b81-b557-0e0cc3899dd1", "type": "concept", "title": "textual evidence"}], "description": "Support opinions with details from articles, films, interviews, and cultural materials."}, {"id": "718047f7-8ff7-4270-9856-90756653bdb3", "type": "subtopic", "title": "Persuasive organization", "children": [{"id": "96034195-fe4c-43e8-9a33-eb9ef85e333d", "type": "concept", "title": "introduction"}, {"id": "d2167a4d-a930-4ace-9f25-f7049eaf76ec", "type": "concept", "title": "supporting points"}, {"id": "befc7bab-ab30-4ead-b2a9-c7ed0cf5ce30", "type": "concept", "title": "counterargument"}, {"id": "82d804f4-224a-4c12-a4f5-8165401d5bd0", "type": "concept", "title": "conclusion"}], "description": "Structure oral and written arguments for clarity and audience impact."}]}, {"id": "b4797825-e67f-4bed-86aa-4ebf0ca800d9", "type": "topic", "title": "Film and Cultural Analysis", "description": "Students use film and visual culture to connect language with history, identity, representation, and social context. The unit develops interpretive vocabulary and prepares students for upper-level Hispanic culture courses.", "children": [{"id": "de9d10e3-4f83-4f47-a556-3d6059917e4f", "type": "subtopic", "title": "Film vocabulary and viewing strategies", "children": [{"id": "237f70e0-c0b6-44e1-984a-e56a8c34547e", "type": "concept", "title": "escena"}, {"id": "1b9e125d-5603-4fe8-a92c-b2f60b8d4ad8", "type": "concept", "title": "personaje"}, {"id": "a3bdb688-baed-416a-a2f8-08e27fadbab9", "type": "concept", "title": "plano"}, {"id": "983064f2-334e-4135-b124-f632b7c06e48", "type": "concept", "title": "sonido"}, {"id": "558235dd-2398-4e00-97dc-824ce6d96e86", "type": "concept", "title": "montaje"}], "description": "Learn the language needed to describe scenes, characters, sound, camera work, and narrative structure."}, {"id": "98a0abed-4944-4e95-8dbb-8c711e9c4ba7", "type": "subtopic", "title": "Culture, history, and context", "children": [{"id": "3bf69547-e3d3-4170-b3a4-42a2328a6f81", "type": "concept", "title": "memory"}, {"id": "0a074ec7-99b5-4758-a6f1-982bc3d3c302", "type": "concept", "title": "migration"}, {"id": "3fd19cdc-400a-48ff-b958-2f3978061d57", "type": "concept", "title": "class"}, {"id": "cfbdd816-34a5-4429-a6d1-927c400a9fe1", "type": "concept", "title": "gender"}, {"id": "aa2b249a-a7bb-42fc-b8b8-6ebb7f0a98c2", "type": "concept", "title": "nation"}], "description": "Interpret cultural products through their social, political, and historical settings."}, {"id": "2937fe51-5b86-474d-96b1-56c54e33f7f6", "type": "subtopic", "title": "Representation and point of view", "children": [{"id": "260779e0-c244-409a-97d7-c6026610a06a", "type": "concept", "title": "stereotypes"}, {"id": "f3a853c3-3902-425b-901a-42f886481b2c", "type": "concept", "title": "voice"}, {"id": "ac56c97c-7d4a-43a6-ac3d-2d4eaeba04b7", "type": "concept", "title": "marginalization"}, {"id": "8b1abf85-83c5-4209-ab11-0691b7c0bbdc", "type": "concept", "title": "power"}], "description": "Analyze how films construct identity, conflict, perspective, and audience sympathy."}, {"id": "c52ceae1-e2f3-46e5-bf7c-d00a580f2740", "type": "subtopic", "title": "Short analytical response", "children": [{"id": "5fabdb74-3f14-4310-bab1-14ad217277a8", "type": "concept", "title": "scene evidence"}, {"id": "18d8f2ac-43da-4c8e-9a12-c9d920b2a853", "type": "concept", "title": "interpretive verbs"}, {"id": "8b09b340-5ee4-4800-989f-62ce315fde0c", "type": "concept", "title": "comparisons"}, {"id": "45e7c51b-f685-43b0-b30d-77ea6c345256", "type": "concept", "title": "discussion questions"}], "description": "Write and discuss interpretations using evidence from specific scenes."}]}, {"id": "99156709-e79a-4572-94f9-40384b329ca2", "type": "topic", "title": "Extended Conversation Practice", "description": "Students build the stamina to sustain unscripted Spanish across longer exchanges. The focus is fluency, repair strategies, follow-up questions, pronunciation, and interactional confidence.", "children": [{"id": "337ebb8e-4a65-4908-8ec3-486703e9d1ab", "type": "subtopic", "title": "Conversation management", "children": [{"id": "4d51e773-57c5-40c0-a07f-6962ef13c17c", "type": "concept", "title": "follow-up questions"}, {"id": "1bb4ca69-e933-4338-8595-c5ee969fa3ee", "type": "concept", "title": "clarification"}, {"id": "a812c160-afc2-497e-8051-dfd7192ea1d7", "type": "concept", "title": "turn-taking"}, {"id": "d5a4825b-4563-4883-8fe9-5107f75d44c9", "type": "concept", "title": "repair phrases"}], "description": "Keep a conversation alive by asking, clarifying, reacting, and redirecting."}, {"id": "a2430130-f40f-4246-bcc4-b2f93da197b6", "type": "subtopic", "title": "Fluency and pronunciation", "children": [{"id": "2ccef700-ff7f-4d80-841e-0061ef5acea7", "type": "concept", "title": "stress"}, {"id": "b6bb9cd0-ac66-44a4-a996-c646b6eff7d8", "type": "concept", "title": "intonation"}, {"id": "361567b6-c4cf-4dd4-8f5d-39933b64cd75", "type": "concept", "title": "linking"}, {"id": "f29cac07-e874-4d98-8af6-3c09fa6e45d9", "type": "concept", "title": "self-monitoring"}], "description": "Increase speed and naturalness while maintaining comprehensibility."}, {"id": "085b5939-cdf9-48dc-b255-367e6de7cec7", "type": "subtopic", "title": "Discussion leadership", "children": [{"id": "f18f8904-81c4-446e-9e96-34e4b6916331", "type": "concept", "title": "opening questions"}, {"id": "57662043-1b41-41bd-9252-1d85c79dcaec", "type": "concept", "title": "summarizing"}, {"id": "d833003e-b61f-497a-a266-e5346f151589", "type": "concept", "title": "inviting participation"}, {"id": "adad4227-6620-43a6-82dd-eae1733c1a06", "type": "concept", "title": "transition phrases